from lib import *
recs=[
R(2110,"Cobbler Apel Gingerbread",
"Ahli gizi ginjal DaVita, Judy dari Pennsylvania, membagikan resep Cobbler Apel Gingerbread yang lezat dan ramah ginjal, pasti disukai seluruh keluarga Anda.",
"8","3/4 cangkir atau 1/8 cobbler",
["4 cangkir apel","1/3 cangkir gula merah","1 sendok makan air lemon","1 cangkir air","3/4 sendok teh kayu manis","2 sendok makan tepung maizena","1 sendok makan cuka sari apel","7 sendok makan susu rendah lemak","1/4 cangkir gula","1 butir telur","2 sendok makan molase ringan","2 sendok makan sirup jagung","2 sendok makan minyak","1 cangkir tepung terigu serbaguna","1/2 sendok teh soda kue","1/2 sendok teh baking powder","1/2 sendok teh jahe bubuk","1/2 cangkir topping dessert kocok"],
["Panaskan oven terlebih dahulu hingga 350° F.","Kupas dan cincang apel. Campurkan apel, gula merah, air lemon, 1 cangkir air, dan 1/2 sendok teh kayu manis dalam panci sedang. Tutup dan masak hingga apel empuk.","Aduk tepung maizena dan 1 sendok makan air, lalu masukkan ke dalam campuran apel yang panas sambil diaduk. Lanjutkan memasak hingga mengental. Tuang campuran apel ke dalam wadah casserole 1-1/2 liter (quart) dan sisihkan.","Tambahkan 1 sendok makan cuka ke dalam susu dan aduk. Sisihkan.","Kocok bersama gula, telur, campuran susu, molase, sirup jagung, dan minyak.","Di mangkuk terpisah, aduk tepung, soda kue, baking powder, jahe, dan sisa 1/4 sendok teh kayu manis. Tambahkan ke campuran telur dan susu yang telah dikocok, lalu kocok hingga halus.","Tuang adonan gingerbread di atas apel dalam wadah casserole. Panggang selama 30 menit.","Sajikan hangat dengan 1 sendok makan topping dessert kocok atau krim kocok."],
["Empat apel berukuran sedang menghasilkan sekitar 4 cangkir.","Bagi penderita diabetes: untuk mengurangi kandungan karbohidrat, ganti gula merah dan gula putih dengan pemanis tanpa kalori Splenda® granular dan campuran gula merah Splenda atau pemanis pilihan Anda. Perubahan ini menurunkan karbohidrat menjadi 26 gram per porsi dan 2 pilihan karbohidrat."],
["1 buah, kalium sedang","1 makanan pokok bertepung","1 berkalori tinggi","1/2 lemak"]),
R(2113,"Salad Brokoli dan Apel",
"Cukup potong dadu, cincang, dan aduk untuk membuat Salad Brokoli dan Apel. Hidangan sehat ini rendah natrium dan kaya rasa.",
"8","3/4 cangkir",
["3/4 cangkir yogurt Yunani plain rendah lemak","1/4 cangkir mayones","2 sendok makan madu","2 sendok makan cuka sari apel","4 cangkir kuntum brokoli segar","1 apel sedang","1/2 cangkir bawang merah","1/4 cangkir peterseli segar","1/2 cangkir cranberry kering manis","1/4 cangkir kenari"],
["Potong kuntum brokoli menjadi potongan kecil seukuran sekali suap. Potong dadu apel tanpa dikupas menjadi potongan kecil seukuran sekali suap. Cincang peterseli segar.","Dalam mangkuk besar, kocok yogurt, mayones, madu, cuka, dan peterseli hingga tercampur.","Tambahkan bahan-bahan yang tersisa dan aduk hingga terlumuri campuran yogurt. Dinginkan di lemari es agar rasanya menyatu. Aduk sesaat sebelum disajikan."],
["Gunakan jenis apel favorit Anda.","Dapat langsung disajikan jika tidak sempat didinginkan.","Salad ini sangat cocok untuk hari raya, tetapi dapat dinikmati sepanjang tahun.","Hiasi dengan peterseli segar tambahan sebelum disajikan jika diinginkan."],
["1 sayuran, kalium sedang","1/2 buah, kalium rendah","1 lemak"]),
R(2115,"Sate Kalkun",
"Cobalah sate dengan kalkun sebagai bahan utamanya. Sate Kalkun yang ramah ginjal ini berukuran pas untuk mengenyangkan.",
"24","1 tusuk sate",
["3 pon dada kalkun tanpa tulang dan tanpa kulit","6 sendok makan saus teriyaki rendah natrium","1-1/2 sendok teh gula","3 sendok teh minyak canola","1 sendok teh jahe bubuk","1/2 sendok teh pala","2 bawang bombai besar","3 paprika manis (merah dan hijau)","40 ons nanas kaleng potong kotak","8 ons jeruk mandarin kaleng","1 cangkir dressing salad raspberry","1/2 pon anggur","24 tusuk sate"],
["Masak dada kalkun pada suhu 350° F selama 1 jam atau hingga termometer daging mencapai 180° F. Biarkan dingin.","Potong kalkun menjadi dadu seukuran sekali suap.","Dalam mangkuk besar, campurkan saus teriyaki rendah natrium, gula, minyak, jahe, dan pala.","Masukkan dadu kalkun ke dalam campuran. Tutup dan diamkan di lemari es selama 30 menit.","Potong bawang bombai dan paprika seukuran tusuk sate. Tiriskan nanas dan jeruk mandarin.","Dengan tusuk sate, tusukkan kalkun, bawang bombai, paprika, dan potongan nanas secara bergantian untuk membuat 24 tusuk sate.","Letakkan sate dalam piring besar yang aman untuk microwave dan tutup dengan kertas lilin. Microwave sate selama 8 menit.","Letakkan sate di piring saji. Tuang dressing di atas sate dan hiasi dengan anggur dan jeruk mandarin sebelum disajikan."],
[],
["2 daging","1/2 buah, kalium rendah","1/2 sayuran, kalium rendah"]),
R(2117,"Gratin Kentang Cetakan Muffin",
"Mengontrol porsi adalah rahasia untuk menyertakan kentang dalam diet rendah kalium. Resep Gratin Kentang Cetakan Muffin dari ahli gizi DaVita, Lisa, menunjukkan cara menyertakan kentang dan keju Parmesan dalam diet ginjal Anda.",
"12","1 muffin",
["3 siung bawang putih","1 kentang besar (1-1/4 pon)","2 sendok makan mentega tanpa garam","2 sendok makan tepung terigu serbaguna","1 cangkir susu 2%","3/4 cangkir keju Parmesan parut","1/4 sendok teh lada hitam bubuk"],
["Cincang halus bawang putih. Kupas dan iris tipis kentang.","Panaskan oven terlebih dahulu hingga 400˚ F. Olesi 12 cetakan muffin dengan semprotan masak antilengket.","Panaskan mentega dalam panci kecil dengan api sedang. Tambahkan bawang putih dan masak hingga harum, sekitar 1 menit.","Tambahkan tepung dan masak selama 1 menit. Tuang susu perlahan sambil terus diaduk hingga saus halus dan mengental, sekitar 5 hingga 6 menit.","Angkat panci dari api dan aduk 1/2 cangkir keju Parmesan ke dalam saus hingga meleleh. Tambahkan lada bubuk dan sisihkan panci.","Tumpuk irisan kentang dalam cetakan muffin yang telah disiapkan, lalu tuang saus di atas kentang. Taburi setiap tumpukan kentang dengan 1 sendok teh sisa keju Parmesan.","Panggang hingga kentang empuk dan kecokelatan, sekitar 25 menit. Biarkan dingin dalam cetakan selama 5 hingga 7 menit. Longgarkan dengan pisau dan keluarkan dari cetakan untuk disajikan."],
["Kentang adalah sayuran dengan kalium lebih tinggi. Berhati-hatilah dengan porsinya. Untuk mengurangi kalium dalam kentang, rendam irisan kentang dalam panci berisi air bersuhu ruang selama 4 jam.","Sajikan kentang dengan telur dan beri segar untuk sarapan yang seimbang."],
["1 makanan pokok bertepung","1 sayuran, kalium sedang","1 lemak"]),
R(2120,"Roti Cranberry Kacang",
"Roti Cranberry Kacang adalah resep lezat dan ramah ginjal dari ahli gizi DaVita.",
"10","1 iris",
["1-1/2 cangkir cranberry segar","2 cangkir tepung terigu serbaguna","1 cangkir gula","1-1/2 sendok teh baking powder","1/2 sendok teh soda kue","1 butir telur besar","1/2 cangkir jus cranberry atau jus apel","1 sendok teh parutan kulit jeruk","2 sendok makan margarin","1/4 cangkir kenari cincang","2 sendok makan air panas"],
["Potong setiap cranberry menjadi dua dan sisihkan.","Panaskan oven terlebih dahulu hingga 350° F. Olesi loyang roti dengan lemak dan alasi dengan kertas lilin. Olesi kertas lilin dengan lemak. Sisihkan.","Ayak tepung, gula, baking powder, dan soda kue bersama-sama dalam mangkuk besar.","Dalam mangkuk terpisah, campurkan jus, parutan kulit jeruk, margarin cair, dan telur kocok. Tambahkan ke campuran tepung dan aduk hanya hingga tepung tercampur.","Masukkan cranberry dan kenari. Aduk bersama air panas.","Tuang adonan ke dalam loyang roti yang telah disiapkan dan panggang selama 1 jam 10 menit. Uji dengan menusukkan tusuk gigi ke dalam roti; jika keluar bersih, roti sudah matang.","Dinginkan roti dalam loyang selama 10 menit, lalu keluarkan dan dinginkan di atas rak kawat. Potong menjadi 10 iris."],
["Kacang tinggi kalium dan fosfor, tetapi boleh disertakan dalam jumlah kecil. 1/4 cangkir kenari dalam resep ini menyumbang 15 mg kalium dan 9 mg fosfor per iris.","Untuk mengurangi karbohidrat dan kalori, ganti 1 cangkir gula dengan 1/2 cangkir campuran gula Splenda© untuk memanggang. Karbohidrat berkurang menjadi 25 gram dan kalori menjadi 160.","Buat satu roti tambahan dan bekukan untuk nanti."],
["1 makanan pokok bertepung","1/2 buah, kalium rendah","1 lemak","1 berkalori tinggi"]),
R(2122,"Seledri Isi Selai Kacang dan Jeli",
"Seledri Isi Selai Kacang dan Jeli adalah camilan sempurna saat Anda ingin menikmati selai kacang namun tetap sehat.",
"4","3 potong",
["4 batang seledri (sedang, 8 inci)","4 sendok makan selai kacang creamy","2 sendok makan jeli"],
["Pangkas ujung batang seledri.","Isi setiap batang seledri dengan 1 sendok makan selai kacang.","Oleskan jeli di atas selai kacang.","Potong setiap batang seledri menjadi 3 potong dan sajikan."],
["Gunakan jeli atau selai buah dengan rasa apa pun.","Masukkan selai kacang dan jeli ke dalam kantong plastik, gunting ujungnya, lalu semprotkan ke batang seledri.","Untuk mengurangi natrium menjadi 38 mg per porsi, gunakan selai kacang tanpa garam.","Tutup dan simpan sisa seledri isi di lemari es. Tahan selama 2-3 hari."],
["1/2 sayuran, kalium sedang","1/2 daging","1/2 lemak"]),
R(2123,"Sup Sosis Telur",
"Sosis dan telur kini bukan hanya untuk sarapan! Ahli gizi ginjal DaVita, Linda dari Ohio, membagikan resep ramah ginjalnya untuk Sup Sosis Telur yang lezat dan cukup mengenyangkan untuk mengusir dingin bahkan di hari musim dingin yang paling beku.",
"4","1-1/2 cangkir",
["1/2 pon daging sapi giling","1/2 sendok teh sage bubuk","1/2 sendok teh lada hitam","1/2 sendok teh basil kering","1/2 sendok teh bawang putih bubuk","4 iris roti kemarin","2 sendok makan minyak zaitun","1 sendok makan campuran bumbu herba Mrs. Dash®","2 siung bawang putih","3 cangkir kaldu ayam rendah natrium","1-1/2 cangkir air","4 sendok makan peterseli segar","4 butir telur besar","2 sendok makan keju parmesan parut"],
["Panaskan oven terlebih dahulu hingga 375° F.","Untuk membuat sosis, campurkan daging sapi giling, sage, lada hitam, basil, dan bawang putih bubuk, lalu sisihkan.","Potong roti menjadi dadu 1″, lalu aduk di atas loyang dengan minyak zaitun dan bumbu Mrs. Dash. Panggang hingga kecokelatan, sekitar 8 menit. Sisihkan.","Remukkan sosis ke dalam panci besar dan goreng hingga matang. Angkat dari panci dan tiriskan di atas tisu dapur.","Sisakan 2 sendok makan minyak sisa masakan di panci. Cincang halus bawang putih dan tumis 1 hingga 2 menit. Tambahkan kaldu, air, dan peterseli cincang. Tutup dan didihkan, lalu kecilkan api dan didihkan perlahan selama 10 menit.","Atur api agar kaldu hampir tidak mendidih. Satu per satu, pecahkan setiap telur ke dalam mangkuk kecil dan masukkan perlahan ke dalam kaldu. Rebus hingga baru mengeras, sekitar 3 menit.","Bagi sosis ke dalam empat mangkuk sup. Pindahkan telur dengan sendok berlubang ke atas sosis. Tuang 1 cangkir kaldu ke setiap mangkuk.","Taburi setiap mangkuk dengan seperempat bagian crouton buatan sendiri dan 1/2 sendok makan keju parmesan."],
["Hati-hati agar telur tidak direbus terlalu lama atau akan menjadi keras.","Nikmati Sup Sosis Telur untuk sarapan, makan siang, atau makan malam."],
["3-1/2 daging 1 makanan pokok bertepung 1 lemak"]),
R(2126,"Puding Chia dengan Beri",
"Jika Anda mencari cara baru menggunakan biji chia, ahli gizi DaVita, Corilee, punya jawabannya: Puding Chia dengan Beri. Puding ini mengandung hampir 9 gram serat, yang sering kali terlalu rendah dalam sebagian besar diet ginjal.",
"4","1/2 cangkir ditambah beri",
["2 cangkir susu almond, rasa vanila manis","1/2 cangkir biji chia","1/4 cangkir kelapa parut manis","1/4 cangkir blueberry segar","4 stroberi besar"],
["Blender susu almond dan biji chia bersama-sama dalam blender.","Tuang campuran ke dalam 4 piring dessert bening. Aduk agar biji chia tersebar merata.","Dinginkan hingga set, sekitar 1 jam di lemari es atau 1/2 jam di freezer.","Taburi setiap porsi dengan 1 sendok makan kelapa parut, 1 stroberi besar, dan 1 sendok makan blueberry sebelum disajikan."],
["Sebagian besar merek susu almond mengandung kalsium tambahan. Jika Anda menjalani diet rendah kalsium, resep ini mungkin bukan pilihan yang baik. Anda dapat menggantinya dengan Susu Almond Buatan Sendiri atau mencari merek tanpa kalsium tambahan.","Biji chia tinggi fosfor, yang menyumbang 200 mg fosfor dalam setiap porsi puding. Diperkirakan hanya 40-60% fosfor dalam biji-bijian utuh, kacang polong, kacang-kacangan, dan biji-bijian yang dapat diserap. Konsultasikan dengan ahli gizi Anda sebelum menyertakan Puding Chia dengan Beri dalam diet Anda."],
["1 pengganti susu non-susu","1/2 buah, kalium rendah","1 berkalori tinggi"]),
R(2127,"Cupcake Stroberi Bebas Gluten",
"Menggabungkan diet ginjal dengan diet bebas gluten memang sulit, tetapi dengan beberapa perubahan bahan, beberapa resep favorit dapat disesuaikan untuk kedua diet. Rekan tim DaVita, Meghan, membagikan resep cupcake favoritnya. Ramah ginjal dan bebas gluten.",
"12","1 cupcake",
["2/3 cangkir stroberi segar utuh","1 cangkir tepung beras putih","1/2 cangkir tepung beras merah","1 sendok teh baking powder","1/4 sendok teh garam","1/4 cangkir susu beras, tanpa fortifikasi","1 sendok teh ekstrak vanila murni","1/2 cangkir mentega tanpa garam","1 cangkir gula","1 butir telur besar","2 putih telur besar"],
["Keluarkan mentega, telur, dan susu beras agar mencapai suhu ruang. Panaskan oven terlebih dahulu hingga 350°F. Letakkan cetakan kertas cupcake dalam loyang muffin 12 lubang; sisihkan.","Haluskan stroberi dalam food processor kecil hingga menjadi puree, menghasilkan sekitar 1/3 cangkir puree.","Dalam mangkuk sedang, campurkan tepung beras putih dan merah, baking powder, dan garam; sisihkan.","Dalam mangkuk kecil, campurkan susu beras, vanila, dan puree stroberi; sisihkan.","Kocok mentega dengan mixer listrik pada kecepatan sedang-tinggi hingga ringan dan mengembang. Tambahkan gula sedikit demi sedikit dan terus kocok hingga tercampur rata dan mengembang. Turunkan kecepatan mixer ke sedang dan tambahkan telur dan putih telur perlahan hingga baru tercampur.","Dengan mixer pada kecepatan rendah, tambahkan setengah campuran tepung beras perlahan; aduk hingga baru tercampur. Tambahkan campuran susu; aduk hingga baru tercampur. Tambahkan sisa campuran tepung beras perlahan, kerok sisi mangkuk dengan spatula bila perlu, hingga baru tercampur.","Tuang adonan ke dalam cetakan muffin. Panggang hingga bagian atas baru terasa kering saat disentuh, 22 hingga 25 menit. Letakkan loyang muffin di atas rak kawat dan biarkan cupcake dingin sebelum dikeluarkan dari loyang."],
["Gunakan stroberi beku jika stroberi segar tidak sedang musim. Cairkan sebelum dihaluskan.","Lapisi cupcake dengan icing favorit Anda (bebas gluten jika diperlukan).","Anda juga dapat membuat resep ini menjadi kue besar, bukan cupcake."],
["1 makanan pokok bertepung","1/2 berkalori tinggi","1-1/2 lemak"]),
R(2132,"Susu Almond Buatan Sendiri",
"Susu almond adalah pengganti susu yang populer, bahkan untuk diet ginjal karena kandungan kalium dan fosfornya rendah. Susu Almond Buatan Sendiri adalah pilihan yang lebih baik karena tidak mengandung kalsium, fosfat, atau bahan tambahan dan pengawet lainnya.",
"3","1 cangkir",
["1 cangkir almond mentah","3 cangkir air saring, ditambah air untuk merendam","1 sendok teh ekstrak vanila"],
["Letakkan almond mentah dalam toples dan tuang air saring hingga terendam. Tutup toples dan rendam pada suhu ruang selama 6 jam, atau semalaman di lemari es.","Tiriskan almond dan masukkan ke dalam blender.","Tambahkan 3 cangkir air saring segar ke dalam blender.","Blender pada kecepatan rendah, secara bertahap naikkan ke kecepatan tinggi. Blender selama 2 menit, hingga cairan menjadi putih dan almond tercincang halus.","Letakkan kain keju atau kantong kacang di atas mangkuk. Tuang cairan secara bertahap untuk menyaring cairan dari ampas almond. Peras kain keju atau kantong kacang untuk mengeluarkan cairannya. Buang ampas almond.","Tambahkan ekstrak vanila dan perisa lain sesuai selera.","Tuang susu almond ke dalam toples, tutup, dan simpan di lemari es hingga 3 hari. Kocok sebelum disajikan."],
["Perisa yang disarankan meliputi sirup maple atau madu, kayu manis bubuk, gula, stevia, Splenda, atau pemanis lain yang diinginkan.","Sesuaikan jumlah air untuk minuman yang lebih kental atau lebih encer.","Ampas almond dibuang karena mengandung sebagian besar fosfor dan sebagian kalium dari kacang. Secara umum susu kacang jauh lebih rendah kalium dan fosfor dibandingkan satu porsi kacang.","Susu almond produksi pabrik mengandung garam tambahan, kalsium, pengental, dan pengemulsi. Beberapa merek juga mengandung bahan tambahan fosfat. Susu almond buatan sendiri bebas garam dan tanpa bahan tambahan."],
["1 alternatif susu"]),
R(2133,"Ayam Marinasi Lemon",
"Cobalah resep Ayam Marinasi Lemon yang segar dan ramah ginjal ini.",
"4","1 dada ayam",
["1/4 cangkir air lemon","1/4 cangkir kaldu ayam rendah natrium","2 sendok makan minyak zaitun","1 sendok teh oregano kering","1 lembar daun salam, diremukkan","1 pon dada ayam tanpa tulang dan tanpa kulit"],
["Campurkan air lemon, kaldu ayam, minyak zaitun, oregano, dan daun salam dalam piring kaca atau kantong zip lock.","Masukkan dada ayam, balik hingga terlumuri, dan marinasi selama 2 jam.","Panggang di bawah broiler atau di atas panggangan sejauh 4-5 inci dari sumber panas selama 5-6 menit per sisi atau hingga matang sempurna."],
["Carilah kaldu rendah natrium yang mengandung kurang dari 500 miligram natrium per porsi 1 cangkir. Hindari kaldu rendah natrium yang mengandung kalium klorida karena sangat tinggi kalium. Merek yang direkomendasikan meliputi Health Valley No Salt, Fat Free Chicken Broth (800-423-4846), Kitchen Basics Natural Chicken Stock, dan Swanson 50% Less Sodium Chicken Broth.","Jika Anda menjalani diet rendah protein, sesuaikan porsi dengan rencana makan Anda."],
["3-1/2 daging"]),
R(2136,"Paprika Hijau Isi",
"Mencari sesuatu yang berbeda untuk makan malam? Cobalah resep Paprika Hijau Isi yang ramah ginjal ini dan tambahkan sedikit kesegaran di meja makan Anda.",
"6","1/2 buah paprika",
["3 paprika hijau","1 pon daging kalkun giling 93-94% tanpa lemak","2 sendok teh mentega tanpa garam (dibagi)","1/4 cangkir bawang bombai, cincang","3 sendok makan salsa mild kental dan berpotongan","1 sendok teh bumbu herba bawang Mrs. Dash®","2 cangkir nasi matang","1/2 cangkir air","1/2 cangkir remah roti putih lembut","1 sendok teh bumbu unggas","1 sendok teh paprika bubuk"],
["Potong paprika menjadi dua dari tangkai hingga dasar. Buang bijinya. Rebus sebentar selama 4 menit.","Dalam wajan besar, masak kalkun giling. Angkat daging dan sisihkan. Buang minyak sisa masakan.","Tumis bawang bombai dalam 1 sendok teh mentega hingga transparan. Tambahkan salsa, bumbu herba Mrs. Dash®, nasi matang, dan daging. Aduk hingga tercampur.","Isi setengah paprika hijau dengan campuran daging dan nasi, lalu letakkan dalam loyang dangkal. Tambahkan 1/2 cangkir air ke dalam loyang.","Campurkan remah roti, bumbu unggas, dan mentega cair. Taburkan di atas paprika isi.","Tutup dan panggang pada suhu 350 F selama 30 menit. Buka tutupnya dan panggang 5 menit hingga kecokelatan."],
["Daging sapi giling dapat digunakan sebagai pengganti kalkun. Ini akan sedikit meningkatkan kandungan lemak.","Untuk variasi, gunakan paprika merah atau oranye sebagai pengganti paprika hijau."],
["2 daging","1 sayuran, kalium sedang","1 makanan pokok bertepung","1 lemak"]),
R(2139,"Smoothie Cali Berry",
"Smoothie menyegarkan ini memadukan bahan-bahan sehat untuk camilan cepat saat bepergian atau saat Anda butuh penyemangat.",
"1","1 cangkir (8 ons)",
["1/4 cangkir blueberry beku","1/4 cangkir stroberi beku","1/4 cangkir susu almond","1/2 cangkir yogurt Yunani, vanila atau plain","1 sendok teh biji rami giling"],
["Masukkan semua bahan ke dalam blender. Pulse atau blender hingga beri halus."],
["Resep ini lebih tinggi kalium, tetapi merupakan pilihan yang baik sebagai pengganti makan yang cepat dan mudah atau untuk sarapan."],
["2-1/2 susu","1 buah, kalium rendah"]),
R(2140,"French Toast Pagi Hari Raya",
"Sambut hari raya yang bahagia dengan resep lezat dan ramah ginjal French Toast Pagi Hari Raya dari ahli gizi ginjal DaVita, Arlene dari California.",
"9","potongan 3” x 4”",
["3/4 cangkir gula merah","1/2 cangkir mentega tanpa garam","3 sendok teh kayu manis","3 apel asam besar","1/2 cangkir cranberry kering manis","1 pon roti Italia","6 butir telur besar","1-1/2 cangkir susu beras, tanpa fortifikasi","1 sendok makan vanila"],
["Kupas, buang bagian tengah, dan iris tipis atau cincang apel.","Dalam loyang 13” x 9”, campurkan gula merah, mentega cair, dan satu sendok teh kayu manis. Tambahkan apel dan cranberry; aduk rata hingga terlumuri.","Ratakan campuran apel di dasar loyang.","Potong roti menjadi irisan 3/4” dan susun di atas apel.","Campurkan telur, susu beras, vanila, dan sisa 2 sendok teh kayu manis hingga tercampur rata. Tuang campuran ke atas roti hingga roti terendam sepenuhnya. Tutup dan simpan di lemari es selama 4 hingga 24 jam.","Panaskan oven terlebih dahulu hingga 375° F.","Panggang tertutup foil selama 30 menit. Buka tutup loyang dan panggang 15 menit atau hingga bagian atas mulai kecokelatan.","Keluarkan loyang dari oven dan diamkan 5 menit sebelum dipotong menjadi 9 porsi.","Sajikan hangat. Taburi bagian atas dengan gula bubuk sebelum disajikan."],
["3 apel besar menghasilkan sekitar 4-1/2 cangkir. Potong menjadi dadu besar, bukan irisan, jika diinginkan.","Potong menjadi porsi lebih kecil 1-1/2” x 2” untuk kalori dan karbohidrat yang lebih rendah.","Gunakan roti Prancis sebagai pengganti roti Italia dan buang kulit roti jika diinginkan."],
["1 daging","1 makanan pokok bertepung","1 buah, kalium rendah","2 lemak","1-1/2 berkalori tinggi"]),
R(2141,"Sup Ayam Mi",
"Nikmati semangkuk sup ayam mi yang dibuat dengan mempertimbangkan diet ginjal. Resep sup ayam mi ini lezat dan menyehatkan.",
"4","1 cangkir",
["1-1/2 cangkir kaldu ayam rendah natrium","1 cangkir air","1/4 sendok teh bumbu unggas","1/4 sendok teh lada hitam","1/4 sendok teh garam","1 cangkir ayam, matang","1/4 cangkir wortel","2 ons mi telur, mentah"],
["Tuang kaldu ayam dan air ke dalam slow cooker dengan pengaturan api tinggi.","Bumbui dengan bumbu unggas, lada, dan garam.","Suwir ayam. Potong dadu kecil wortel.","Tambahkan ayam, wortel, dan mi telur ke dalam sup.","Masak dengan pengaturan api tinggi selama 20 hingga 25 menit atau hingga mi matang."],
["Resep ini paling enak jika dibuat dengan kaldu ayam buatan sendiri, bukan kaldu kaleng.","Mi fettuccine cocok digunakan dalam resep ini sebagai pengganti mi telur. Jangan terlalu matang atau mi akan lembek.","Hilangkan garam jika menggunakan kaldu siap pakai yang mengandung lebih dari 140 mg natrium per cangkir.","Masak seekor ayam utuh dalam slow cooker untuk membuat kaldu dan menyediakan sebagian ayam untuk resep ini. (Lihat Ayam Utuh Slow Cooker.)"],
["2 daging","1 makanan pokok bertepung"]),
]
